  // Settings
  'Settings': 'Ayarlar',
  'Defaults apply to new researches. Each research keeps the models it was created with, and you can change them for one research from the composer.': 'Varsayılanlar yeni araştırmalara uygulanır. Her araştırma oluşturulduğu modelleri korur; tek bir araştırma için modelleri soru kutusundan değiştirebilirsiniz.',
