  'Citation chaining': 'Atıf zinciri',
  'After the abstracts are read, OpenAlex is asked for the works that the first {seeds} works of the ranking and every work you verified cite, and for the works that cite them. A new work is kept when a setting or task term stands in its title or abstract; the list of seeds is shown in the run once the search is done.': 'Özetler okunduktan sonra OpenAlex\'e sıralamanın ilk {seeds} eserinin ve doğruladığınız her eserin atıf yaptığı eserler ile bunlara atıf yapan eserler sorulur. Yeni bir eser, başlığında ya da özetinde bir bağlam ya da görev terimi geçiyorsa tutulur; tohum listesi arama bittikten sonra koşuda gösterilir.',
  'Citation chaining is turned off in the settings; this run follows no citation.': 'Atıf zinciri ayarlarda kapalı; bu koşu hiçbir atıfı izlemez.',
  'Up to {cap} citing works per seed · at most {requests} requests · the model reads up to {read} new works · up to {room} of them join the full-text plan, beside its own limit': 'Tohum başına en çok {cap} atıf yapan eser · en çok {requests} istek · model en çok {read} yeni eser okur · bunların en çok {room} tanesi tam metin planına, planın kendi sınırının yanında girer',
