  'Marker reads PDF pages with mathematics from the page image and writes their equations as LaTeX, so answers and table cells read the equations instead of broken PDF text. It runs on this computer; no file leaves it. Answers and cells wait until the equations of the PDFs they read are read.': 'Marker, matematik içeren PDF sayfalarını sayfa görüntüsünden okur ve denklemleri LaTeX olarak yazar; böylece cevaplar ve tablo hücreleri bozuk PDF metni yerine denklemleri okur. Bu bilgisayarda çalışır; hiçbir dosya dışarı çıkmaz. Cevaplar ve hücreler, okudukları PDF’lerin denklemleri okunana kadar bekler.',
  'About one Marker equation in fifty was misread in a test on three papers, and a misread equation looks correct. Equations that do not match the PDF’s own text are marked to check against the page.': 'Üç makalelik bir denemede Marker’ın yaklaşık elli denklemden biri yanlış okundu ve yanlış okunan denklem doğru görünüyor. PDF’in kendi metniyle uyuşmayan denklemler, sayfayla karşılaştırılmak üzere işaretlenir.',
