  'It cannot be removed while a PDF is being read': 'Bir PDF okunurken kaldırılamaz',
  'Install the equation reader?': 'Denklem okuyucu kurulsun mu?',
  'This downloads Marker and its models, about 4.4 GB, into the DEIXIS data folder. It can take several minutes. Marker’s code is GPL-3.0 and its models have their own license. Afterwards the stored PDFs are read in the background; that can take hours for a large library.': 'Marker ve modelleri (yaklaşık 4,4 GB) DEIXIS veri klasörüne indirilir. Birkaç dakika sürebilir. Marker’ın kodu GPL-3.0 lisanslıdır, modellerinin kendi lisansı vardır. Ardından kayıtlı PDF’ler arka planda okunur; büyük bir kütüphanede bu saatler sürebilir.',
  'Remove the equation reader?': 'Denklem okuyucu kaldırılsın mı?',
  'Marker and its models are deleted. Equations already read stay in the stored text; new PDFs are no longer read.': 'Marker ve modelleri silinir. Okunmuş denklemler kayıtlı metinde kalır; yeni PDF’ler artık okunmaz.',
