  'A changed definition becomes a new column revision. Values made under the earlier definition stay and are marked “Column changed”.': 'Değişen tanım yeni bir sütun revizyonu olur. Önceki tanımla üretilen değerler kalır ve “Sütun değişti” diye işaretlenir.',
