  'Empty: no value recorded yet.': 'Boş: henüz değer kaydedilmedi.',
  'Rechecking this cell…': 'Bu hücre yeniden inceleniyor…',
  'Made under an earlier definition of this column (revision {old}). It stays until you edit it or use a newer proposal.': 'Bu sütunun önceki bir tanımıyla üretildi (revizyon {old}). Siz düzenleyene ya da daha yeni bir öneriyi kullanana kadar kalır.',
  'A PDF this value cites was removed from the source. The cited passages still open as text; the PDF view is off.': 'Bu değerin dayandığı bir PDF kaynaktan kaldırıldı. Pasajlar metin olarak açılmaya devam eder; PDF görünümü kapalıdır.',
  'This value cites a PDF that was later replaced. Its evidence still opens the previous file; a recheck reads the current file.': 'Bu değer sonradan değiştirilen bir PDF’ye dayanıyor. Kanıtı önceki dosyayı açmaya devam eder; yeniden inceleme güncel dosyayı okur.',
  'This value cites an earlier text extraction of the PDF. Its evidence still opens that text; a recheck reads the current extraction.': 'Bu değer PDF’nin önceki bir metin çıkarımına dayanıyor. Kanıtı o metni açmaya devam eder; yeniden inceleme güncel çıkarımı okur.',
  'Previous PDF': 'Önceki PDF',
  'Earlier text': 'Eski metin',
  'Replace PDF': 'PDF’yi değiştir',
  'Replace PDF?': 'PDF değiştirilsin mi?',
  'Use another file for this source version; evidence that cites the current file keeps it': 'Bu kaynak sürümü için başka bir dosya kullan; mevcut dosyaya dayanan kanıt onu korur',
  'Extract text again': 'Metni yeniden çıkar',
  'Text extracted as {version}. Extract it again with the current extractor.': 'Metin {version} ile çıkarıldı. Güncel çıkarıcıyla yeniden çıkar.',
  '{file} will be read in later answers and cells instead of the current file. The current file is not deleted: evidence that cites it keeps opening it.': 'Sonraki yanıt ve hücrelerde mevcut dosya yerine {file} okunacak. Mevcut dosya silinmez: ona dayanan kanıt onu açmaya devam eder.',
  'The source is used in {n} research;': 'Kaynak {n} araştırmada kullanılıyor;',
  'The source is used in {n} researches;': 'Kaynak {n} araştırmada kullanılıyor;',
  '{cells} evidence table cells and {quotes} answer quotes cite the current file.': 'mevcut dosyaya {cells} kanıt tablosu hücresi ve {quotes} yanıt alıntısı dayanıyor.',
  'PDF replaced. Its text was extracted page by page (no OCR); earlier evidence still opens the previous file.': 'PDF değiştirildi. Metni sayfa sayfa çıkarıldı (OCR yok); önceki kanıt eski dosyayı açmaya devam eder.',
  'The new extraction was not used: {reason}. The earlier text stays in use.': 'Yeni çıkarım kullanılmadı: {reason}. Önceki metin kullanılmaya devam ediyor.',
  'This text already comes from the current extractor.': 'Bu metin zaten güncel çıkarıcıdan geliyor.',
  'Text extracted again. Later answers and cells read the new text; earlier evidence still opens the text it cited.': 'Metin yeniden çıkarıldı. Sonraki yanıt ve hücreler yeni metni okur; önceki kanıt dayandığı metni açmaya devam eder.',
  'A later text extraction ({version}) was not used: {reason}. The earlier text stays in use.': 'Sonraki bir metin çıkarımı ({version}) kullanılmadı: {reason}. Önceki metin kullanılmaya devam ediyor.',
  'Previous file {file} replaced on {date}. Evidence that cites it still opens it.': 'Önceki dosya {file}, {date} tarihinde değiştirildi. Ona dayanan kanıt onu açmaya devam eder.',
  'Previous PDF replaced on {date}. Evidence that cites it still opens it.': 'Önceki PDF {date} tarihinde değiştirildi. Ona dayanan kanıt onu açmaya devam eder.',
  'A PDF this answer read was replaced, removed or had its text extracted again after the answer was generated. Its quotes still open the text that was read; generate a new answer to read the current text.': 'Bu yanıtın okuduğu bir PDF, yanıt üretildikten sonra değiştirildi, kaldırıldı ya da metni yeniden çıkarıldı. Alıntılar okunan metni açmaya devam eder; güncel metni okumak için yeni bir yanıt üretin.',
  'PDF replaced on a source': 'Bir kaynağın PDF’si değiştirildi',
  'PDF text extracted again': 'PDF metni yeniden çıkarıldı',
  'in use': 'kullanımda',
  'This passage comes from a PDF that was later replaced. It opens the previous file, which is no longer read in new answers or cells.': 'Bu pasaj sonradan değiştirilen bir PDF’den geliyor. Önceki dosyayı açar; o dosya yeni yanıt ve hücrelerde artık okunmaz.',
  'This passage comes from a PDF that was removed from the source. Its stored text still opens; the PDF view is off.': 'Bu pasaj kaynaktan kaldırılan bir PDF’den geliyor. Saklı metni açılmaya devam eder; PDF görünümü kapalıdır.',
  'This passage comes from an earlier text extraction ({version}). New answers and cells read the current extraction, which may split or word the page differently.': 'Bu pasaj önceki bir metin çıkarımından ({version}) geliyor. Yeni yanıt ve hücreler güncel çıkarımı okur; sayfa orada farklı bölünmüş ya da yazılmış olabilir.',
  'No linked evidence: this value was recorded without a passage.': 'Bağlı kanıt yok: bu değer bir pasaj olmadan kaydedildi.',
