  'Proposal': 'Öneri',
  'Requested before the cell last changed. Compare it with the current value before using it.': 'Hücre son değişmeden önce istendi. Kullanmadan önce geçerli değerle karşılaştırın.',
  'This proposal failed validation after one repair. It is kept for the record and cannot be used.': 'Bu öneri bir onarımdan sonra doğrulamayı geçemedi. Kayıt için saklanır ve kullanılamaz.',
  'The proposal’s value and evidence are now the cell’s value, recorded as your decision.': 'Önerinin değeri ve kanıtı artık hücrenin değeri; sizin kararınız olarak kaydedildi.',
