  'Recheck this cell': 'Bu hücreyi yeniden incele',
  'This source has no stored text, so a recheck has nothing to read.': 'Bu kaynağın kayıtlı metni olmadığı için yeniden incelemenin okuyacağı bir şey yok.',
  'Another run is active; a recheck can start when it finishes.': 'Başka bir işlem çalışıyor; yeniden inceleme o bitince başlatılabilir.',
  'Only {source} · up to {n} passage · {model} · 1–2 calls. The result waits as a proposal; the model does not see the current value.': 'Yalnız {source} · en fazla {n} pasaj · {model} · 1–2 çağrı. Sonuç öneri olarak bekler; model geçerli değeri görmez.',
  'Only {source} · up to {n} passages · {model} · 1–2 calls. The result waits as a proposal; the model does not see the current value.': 'Yalnız {source} · en fazla {n} pasaj · {model} · 1–2 çağrı. Sonuç öneri olarak bekler; model geçerli değeri görmez.',
