  'The library record and its PDF were not deleted, and earlier quotes still open. Deleting one permanently also deletes its library record, passages and PDF, unless another research holds the source or evidence still cites it.': 'Kütüphane kaydı ve PDF’i silinmedi; eski alıntılar açılmaya devam eder. Kalıcı olarak silerseniz kütüphane kaydı, pasajları ve PDF’i de silinir; kaynağı başka bir araştırma tutuyorsa ya da bir kanıt hâlâ ona atıf veriyorsa kalır.',
