  'The research loses its record of {n} sources. Their library records, passages and PDFs go too, unless another research holds them. This cannot be undone.': 'Araştırma {n} kaynağa dair kaydını kaybeder. Kaynakları başka bir araştırma tutmuyorsa kütüphane kayıtları, pasajları ve PDF’leri de silinir. Bu işlem geri alınamaz.',
