  'English only': 'Yalnız İngilizce',
  'Languages missing': 'Eksik dil var',
  'Installed · languages missing': 'Kurulu · eksik dil var',
  'Tesseract reads PDF pages that have no text layer, such as scanned articles, when you choose Read with OCR on a source. It runs on this computer; no file leaves it, and the PDF is not changed.': 'Tesseract, bir kaynakta “OCR ile oku”yu seçtiğinizde taranmış makaleler gibi metin katmanı olmayan PDF sayfalarını okur. Bu bilgisayarda çalışır; hiçbir dosya dışarı çıkmaz ve PDF değiştirilmez.',
  'OCR text is labelled wherever it is quoted. On four scanned articles about 0.2–1.5% of characters were misread and equations were unusable; numbers and equations from OCR text are not checked against the page.': 'OCR metni alıntılandığı her yerde etiketlenir. Dört taranmış makalede karakterlerin yaklaşık %0,2–1,5’i yanlış okundu ve denklemler kullanılamaz durumdaydı; OCR metnindeki sayı ve denklemler sayfayla karşılaştırılmaz.',
  'Languages': 'Diller',
  'Missing': 'Eksik',
  'Source key': 'Kaynak etiketi',
  'Open source details': 'Kaynak ayrıntılarını aç',
  'No abstract or PDF text is stored for this source.': 'Bu kaynak için saklanmış bir özet ya da PDF metni yok.',
  // The protocol approval card and the sw workflow's own stops (D80)
  'This run has not searched yet. Check the search terms and the inclusion criterion below, correct them if needed, and approve them.': 'Bu koşu henüz arama yapmadı. Aşağıdaki arama terimlerini ve dahil etme ölçütünü gözden geçirin, gerekiyorsa düzeltin ve onaylayın.',
  'DEIXIS reads search terms from an English question and does not translate. Revise the question in English, or give the English key terms below.': 'DEIXIS arama terimlerini İngilizce sorudan okur ve çeviri yapmaz. Soruyu İngilizce olarak yeniden yazın ya da aşağıya İngilizce anahtar terimleri girin.',
  'No term is left that a provider query could be built from. Add a term below, or move one back into the setting or task block.': 'Sağlayıcı sorgusu kurulabilecek hiçbir terim kalmadı. Aşağıdan bir terim ekleyin ya da bir terimi ortam veya iş bloğuna geri taşıyın.',
  'Every remaining term is too frequent to search on its own, and they are all in one block. Add a term to the other block, or replace one with a narrower phrase.': 'Kalan terimlerin hepsi tek başına aranamayacak kadar sık geçiyor ve hepsi tek blokta. Öbür bloğa bir terim ekleyin ya da terimlerden birini daha dar bir ifadeyle değiştirin.',
  'Setting': 'Ortam',
  'Task': 'İş',
  'Outcome': 'Sonuç',
  'Claim under test': 'Sınanan iddia',
  'Excluded words': 'Dışlanan sözcükler',
  'Searched: one part of the provider query.': 'Aranır: sağlayıcı sorgusunun bir parçası.',
  'Searched: the other part of the provider query.': 'Aranır: sağlayıcı sorgusunun öbür parçası.',
  'Not searched; used to order the records that were found.': 'Aranmaz; bulunan kayıtları sıralamak için kullanılır.',
  'Not searched: a record that states the claim is what the search is looking for.': 'Aranmaz: aramanın aradığı şey, bu iddiayı söyleyen kayıttır.',
  'Not searched. Kept with the protocol; in this version no record is kept out by them yet.': 'Aranmaz. Protokolle birlikte saklanır; bu sürümde henüz hiçbir kaydı dışarıda tutmaz.',
