  'The model has already been asked for this question; its proposals are below.': 'Bu soru için model bir kez soruldu; önerileri aşağıda.',
  'Other names for these terms': 'Bu terimlerin başka adları',
  'A model can propose names the literature uses for the same things. Nothing it proposes is searched unless you add it.': 'Model, aynı şeyler için yazının kullandığı adları önerebilir. Önerdiği hiçbir ad siz eklemedikçe aramaya girmez.',
  'Ask the model for other names': 'Modelden terim öner',
  'One request per question. Each proposal is counted against the literature, and none enters the search unless you add it.': 'Soru başına bir istek. Her öneri yazında sayılır ve siz eklemedikçe hiçbiri aramaya girmez.',
