  'Every term that would be searched is too frequent to stand alone. You can still approve; the run will stop again and say so.': 'Aranacak terimlerin hepsi tek başına durabilmek için fazla sık geçiyor. Yine de onaylayabilirsiniz; koşu yeniden durur ve nedenini söyler.',
  'No term is left to build a provider query from. Add one below, or move one back into the setting or task block.': 'Sağlayıcı sorgusu kurulabilecek terim kalmadı. Aşağıdan bir terim ekleyin ya da bir terimi ortam veya iş bloğuna geri taşıyın.',
