  'No criterion was proposed: the model was not reachable while this run worked. You can go on without one, or write one yourself.': 'Ölçüt önerilmedi: bu koşu çalışırken modele ulaşılamadı. Ölçütsüz sürdürebilir ya da kendiniz yazabilirsiniz.',
