  'Recorded as not meeting the criterion.': 'Ölçütü karşılamıyor olarak kaydedildi.',
  'Left as awaiting a decision; it does not come back to the queue by itself.': 'Karar bekliyor olarak bırakıldı; kuyruğa kendiliğinden dönmez.',
  'PDF marked as wrong; the work moved to those waiting for a PDF.': 'PDF yanlış olarak işaretlendi; eser PDF bekleyenlere geçti.',
  'PDF confirmed; the next reading run reads this work. No run starts by itself.': 'PDF onaylandı; bir sonraki okuma koşusu bu eseri okur. Koşu kendiliğinden başlamaz.',
  'Your decision was taken back.': 'Kararınız geri alındı.',
  'The reading has begun, so this confirmation can no longer be taken back; you can decide about the work instead.': 'Okuma başladığı için bu onay geri alınamıyor; eser için karar verebilirsiniz.',
  'This decision changed after it was shown, so it was not taken back. The latest state is loaded.': 'Bu karar gösterildikten sonra değişti, geri alınmadı. Güncel hâli yüklendi.',
  'This row changed after it was shown; its current state is loaded. Your answer was not saved.': 'Bu satır gösterildikten sonra değişti; güncel hâli yüklendi. Cevabınız kaydedilmedi.',
  'The row you answered left the queue after it was shown. Your answer was not saved.': 'Cevapladığınız satır gösterildikten sonra kuyruktan çıktı. Cevabınız kaydedilmedi.',
  'This work is no longer in the queue. Nothing was saved; your note is kept below.': 'Bu eser artık kuyrukta değil. Hiçbir şey kaydedilmedi; notunuz aşağıda duruyor.',
  'This row changed while it was loading; the queue is being read again.': 'Bu satır yüklenirken değişti; kuyruk yeniden okunuyor.',
  '{locator}: a sentence on this page holds a phrase of this part. Nothing is marked.': '{locator}: bu sayfadaki bir cümle bu parçanın ifadelerinden birini taşıyor. Hiçbir şey işaretlenmedi.',
  '{locator}. Nothing is marked.': '{locator}. Hiçbir şey işaretlenmedi.',
  'The model’s quote, found in the text of {locator}. Only the text found on the page is marked.': 'Modelin alıntısı {locator} metninde bulundu. Yalnız sayfada bulunan metin işaretlidir.',
  'The quote could not be marked exactly in the text of {locator}, so nothing is marked. Check the page in the PDF.': 'Alıntı {locator} metninde tam olarak işaretlenemedi, bu yüzden hiçbir şey işaretlenmedi. Sayfayı PDF’te denetleyin.',
  'The model’s quote, as found in the page text': 'Modelin alıntısı, sayfa metninde bulunduğu hâliyle',
  'Your note for “{title}” is kept here:': '“{title}” için yazdığınız not burada duruyor:',
  'Reading this row again…': 'Bu satır yeniden okunuyor…',
  'This row kept changing while it was read, so it cannot be answered yet.': 'Bu satır okunurken değişmeye devam etti, bu yüzden henüz cevaplanamıyor.',
  'Read it again': 'Yeniden oku',
  'The reading has begun, so this can no longer be taken back.': 'Okuma başladı, bu yüzden artık geri alınamaz.',
  'The model’s quote was not found in the text, so nothing on {locator} is marked. Check the page in the PDF.': 'Modelin alıntısı metinde bulunamadı, bu yüzden {locator} üzerinde hiçbir şey işaretlenmedi. Sayfayı PDF’te denetleyin.',
  'The model’s quote was not found in the text of the page it named, so nothing is marked. Check the page in the PDF.': 'Modelin alıntısı adını verdiği sayfanın metninde bulunamadı, bu yüzden hiçbir şey işaretlenmedi. Sayfayı PDF’te denetleyin.',
  'Run {n}': '{n}. koşu',
  'Run {run}: the model’s quote was not found in the text. The closest text is beside it; match ratio {ratio}.': '{run}. koşu: modelin alıntısı metinde bulunamadı. En yakın metin yanında; eşleşme oranı {ratio}.',
  'Run {run}: the model’s quote was not found in the text, and the pages this run was shown hold no close text.': '{run}. koşu: modelin alıntısı metinde bulunamadı ve bu koşuya gösterilen sayfalarda yakın metin yok.',
  'The closest text': 'En yakın metin',
  'The closest text · {locator}': 'En yakın metin · {locator}',
  'The model’s quote': 'Modelin alıntısı',
  'Semantic support not checked. Your answer is recorded as your decision; DEIXIS does not say whether it is right.': 'Anlamsal destek denetlenmedi. Cevabınız sizin kararınız olarak kaydedilir; DEIXIS doğru olup olmadığını söylemez.',
  'Sentences with this part’s phrases': 'Bu parçanın ifadelerini taşıyan cümleler',
  'This part’s phrases do not occur in the text.': 'Bu parçanın ifadeleri metinde geçmiyor.',
  '{shown} of {total} sentences shown': '{total} cümleden {shown} tanesi gösteriliyor',
  'Why it is here:': 'Neden kuyrukta:',
  'Both runs found every part, but a quote was not found on the page it was taken from.': 'İki koşu da her parçayı buldu, ama bir alıntı alındığı sayfada bulunamadı.',
  'The two reading runs came to different readings of the text.': 'İki okuma koşusu metni farklı okudu.',
  'Two versions of this work were read, and their decisions are opposite.': 'Bu eserin iki sürümü okundu ve kararları zıt.',
  'The first page of the PDF does not name this work, so the model has not read it.': 'PDF’nin ilk sayfası bu eseri anmıyor, bu yüzden model onu okumadı.',
  'The title names a study protocol, so the reading neither included nor excluded this work.': 'Başlık bir çalışma protokolünü adlandırıyor, bu yüzden okuma bu eseri ne dahil etti ne dışarıda bıraktı.',
  'Both runs found parts missing, but the criterion has a comparison group, so the reading did not exclude this work.': 'İki koşu da bazı parçaları bulamadı, ama ölçütte bir karşılaştırma grubu var, bu yüzden okuma bu eseri dışarıda bırakmadı.',
  'Neither run could tell from the text whether the parts are there.': 'İki koşu da parçaların metinde olup olmadığını söyleyemedi.',
  'The abstract promises a part the text does not show.': 'Özet, metnin göstermediği bir parçayı vaat ediyor.',
  'The runs found some of the criterion’s parts, but not this one.': 'Koşular ölçütün bazı parçalarını buldu, bunu bulmadı.',
  'You included this work under an earlier question or criterion.': 'Bu eseri eski bir soru ya da ölçütle dahil ettiniz.',
