  'Links open through your institution’s proxy in your browser; DEIXIS sends nothing through it.': 'Bağlantılar tarayıcınızda kurumunuzun vekil sunucusu üzerinden açılır; DEIXIS onun üzerinden hiçbir istek göndermez.',
