  'The links of works waiting for your PDF open through this address in your browser, where your institution asks you to sign in. DEIXIS sends nothing through it, downloads nothing from it and never stores a password. Whether your institution grants access is not checked.': 'PDF’inizi bekleyen eserlerin bağlantıları tarayıcınızda bu adres üzerinden açılır; giriş yapmanızı kurumunuz ister. DEIXIS bu adres üzerinden hiçbir istek göndermez, hiçbir şey indirmez ve parola saklamaz. Kurumunuzun erişim verip vermediği denetlenmez.',
