  'A paused run holds back the reading of your files. Resume it or cancel it; no other run starts while it is paused.': 'Duraklatılmış bir koşu dosyalarınızın okunmasını bekletiyor. Sürdürün ya da iptal edin; o duraklatılmışken başka koşu başlamaz.',
