  'Every version of this work already has a PDF in use. A file is not replaced or removed here, so this work cannot take a new one.': 'Bu eserin her sürümünde kullanımda bir PDF var. Burada dosya değiştirilmez ya da kaldırılmaz; bu yüzden bu eser yeni dosya alamaz.',
  'This file has no text layer: it is attached, and the work keeps waiting for a PDF with text.': 'Bu dosyanın metin katmanı yok: eklenir ve eser metni olan bir PDF beklemeyi sürdürür.',
  'You said the file of the {wrong} version was wrong. This file goes to the {chosen} version and the model reads it; your answer about the {wrong} version stands.': '{wrong} sürümünün dosyasını yanlış demiştiniz. Bu dosya {chosen} sürümüne eklenir ve model onu okur; {wrong} sürümü hakkındaki yanıtınız durur.',
