  'Your decisions in this question revision: {list}. {agreed} included by two agreeing runs, not confirmed by you.': 'Bu soru revizyonundaki kararlarınız: {list}. İki uyuşan koşunun dahil ettiği {agreed}; siz onaylamadınız.',
