  'The embedding moved up {n} records. Decided after the ranking: {included} included by two agreeing runs, {verified} you confirmed; {before} decided before it; {unknown} with no readable order. A moved-up record could be decided because it was read.': 'Gömme {n} kaydı öne aldı. Sıralamadan sonra karar verilen: iki uyuşan koşunun dahil ettiği {included}, onayladığınız {verified}; ondan önce karar verilen {before}; sırası okunamayan {unknown}. Öne alınan bir kayıt okunduğu için karar almış olabilir.',
