  // The flow, the audit sample and the PRISMA-S search report (slice 20, D102).
  '{included} included (two agreeing runs {agreed}, you confirmed {confirmed}) · {queued} in your queue, not looked at · {waiting} waiting for a PDF · {notRead} full text not read ({reading} in reading, {tried} not tried) · {notMet} criterion not met': '{included} dahil (iki uyuşan koşu {agreed}, sizin onayladığınız {confirmed}) · kuyruğunuzda bakılmamış {queued} · PDF bekleyen {waiting} · tam metni okunmamış {notRead} (okumada {reading}, denenmemiş {tried}) · ölçütü karşılamayan {notMet}',
  'Flow': 'Akış',
  'Where each of the {n} works stands': '{n} eserin her biri nerede duruyor',
  'Other, by reason code: {list}': 'Diğer, neden koduna göre: {list}',
  'An abstract not read is not an exclusion: the work was not read.': 'Okunmamış özet bir dışlama değildir: eser okunmadı.',
  'Your queue by reason: {list}': 'Nedene göre kuyruğunuz: {list}',
  'Counts in the style of PRISMA 2020': 'PRISMA 2020 biçiminde sayılar',
  'Incomplete: code and model runs did the screening, and you looked only at your queue and the audit sample. The counts are not added up.': 'Eksik: taramayı kod ve model koşuları yaptı, siz yalnızca kuyruğunuza ve denetim örneğine baktınız. Sayılar toplanmaz.',
  'Search report (PRISMA-S)': 'Arama raporu (PRISMA-S)',
  'The search reported against the 16 PRISMA-S items, as Markdown': 'Aramanın 16 PRISMA-S maddesine göre raporu, Markdown olarak',
  'The search reported against the 16 PRISMA-S items, as JSON': 'Aramanın 16 PRISMA-S maddesine göre raporu, JSON olarak',
  'Flow at the start of this answer': 'Bu yanıtın başındaki akış',
  'When the answer started: included {included} (two agreeing runs {agreed}, you confirmed {confirmed}); in your queue, not looked at {queued}; waiting for a PDF {waiting}; full text not read {notRead} ({reading} in reading, {tried} not tried); criterion not met {notMet}.': 'Yanıt başladığında: dahil {included} (iki uyuşan koşu {agreed}, sizin onayladığınız {confirmed}); kuyruğunuzda bakılmamış {queued}; PDF bekleyen {waiting}; tam metni okunmamış {notRead} (okumada {reading}, denenmemiş {tried}); ölçütü karşılamayan {notMet}.',
  'The state of the included sources changed while the answer ran.': 'Yanıt çalışırken dahil edilen kaynakların durumu değişti.',
  'The flow at the start of this answer was not recorded.': 'Bu yanıtın başındaki akış kaydedilmedi.',
  'Given to the model: works {sources}, passages {passages}.': 'Modele verilen: eser {sources}, pasaj {passages}.',
  'not sure {n}': 'emin değilim {n}',
  'wrong PDF {n}': 'yanlış PDF {n}',
  'to look at again {n}': 'yeniden bakılacak {n}',
  'You have not decided yet; this line says nothing about how right code or the model is.': 'Henüz karar vermediniz; bu satır kodun ya da modelin ne kadar haklı olduğu hakkında bir şey söylemez.',
  'Counted apart: {list}.': 'Ayrı sayılanlar: {list}.',
  '{n} included work gave the answer no text: its only text is your file, not read yet.': 'Dahil edilen {n} eser yanıta metin vermedi: tek metni sizin dosyanız ve henüz okunmadı.',
  '{n} included works gave the answer no text: their only text is your file, not read yet.': 'Dahil edilen {n} eser yanıta metin vermedi: tek metinleri sizin dosyanız ve henüz okunmadı.',
  '{n} work rests on a decision you made under the earlier criterion.': '{n} eser, önceki ölçüt altında verdiğiniz bir karara dayanıyor.',
  '{n} works rest on a decision you made under the earlier criterion.': '{n} eser, önceki ölçüt altında verdiğiniz bir karara dayanıyor.',
  'Of your {n} decision, you changed a decision of code or the model runs in {m} (code {code}, model runs {model}).': '{n} kararınızın {m} tanesinde kodun ya da model koşularının kararını değiştirdiniz (kod {code}, model koşuları {model}).',
  'Of your {n} decisions, you changed a decision of code or the model runs in {m} (code {code}, model runs {model}).': '{n} kararınızın {m} tanesinde kodun ya da model koşularının kararını değiştirdiniz (kod {code}, model koşuları {model}).',
  'This audit row changed after it was shown; its current state is loaded. Nothing was saved.': 'Bu denetim satırı gösterildikten sonra değişti; güncel hâli yüklendi. Hiçbir şey kaydedilmedi.',
  'Could not load the audit sample: {error}': 'Denetim örneği yüklenemedi: {error}',
  'Audit sample': 'Denetim örneği',
  'A few works that code or the model runs decided without asking you, drawn by a fixed digest ({n} per group). A later reading can change the sample. The counts are counts, not rates.': 'Kodun ya da model koşularının size sormadan karar verdiği birkaç eser, sabit bir özetle çekildi (grup başına {n}). Sonraki bir okuma örneği değiştirebilir. Sayılar sayıdır, oran değildir.',
  'works in this group: {n}': 'bu gruptaki eser: {n}',
  'Current sample: you looked at {answered} of {n} rows; you decided differently in {differs}.': 'Güncel örnek: {n} satırın {answered} tanesine baktınız; {differs} tanesinde farklı karar verdiniz.',
  'No work is in this group.': 'Bu grupta eser yok.',
