  'Sample of works left out at the abstract stage (view and manual selection)': 'Özet aşamasında dışarıda bırakılan eserlerden örnek (görüntüleme ve elle seçim)',
  'To include or exclude one of these, find it in the source list and use its own controls. An inclusion there does not send it to full-text reading: it goes straight into the answer’s input. Sending it back to full-text reading is not built yet.': 'Bunlardan birini dahil etmek ya da dışlamak için kaynak listesinde bulun ve oradaki kendi düğmelerini kullanın. Orada dahil etmek onu tam metin okumasına göndermez: doğrudan yanıtın girdisine gider. Tam metin okumasına geri gönderme henüz yapılmadı.',
  'Find it in the source list': 'Kaynak listesinde bul',
