  "{prefix}; the edited text was checked by code rules ({date}): {errors}, {warnings}; whether the cited evidence supports each sentence was not checked.": "{prefix}; düzenlenen metin kod kurallarıyla denetlendi ({date}): {errors}, {warnings}; atıf yapılan kanıtın her cümleyi destekleyip desteklemediği denetlenmedi.",
  "{prefix}; the last check ({date}) does not cover the current inputs; whether the cited evidence supports each sentence was not checked.": "{prefix}; son denetim ({date}) güncel girdileri kapsamıyor; atıf yapılan kanıtın her cümleyi destekleyip desteklemediği denetlenmedi.",
  "Out of date": "Güncel değil",
